using System.Text.Json;
using Jellyfin.Plugin.AoideSidecar.Next;
using Xunit;

namespace Jellyfin.Plugin.AoideSidecar.Tests;

/// <summary>
/// The fixture for <c>/aoide/discover</c>: twenty-two records, a week of listening on
/// either side of a Monday, one flag, and five requests with every candidate's score and
/// taste to six decimals, in order, plus a table of ISO weeks across a year's turn.
/// </summary>
/// <remarks>
/// Generated by a reference written apart from this port, from the rules stated in the
/// file. The clients add the same file beside <c>next-ranking-fixture.json</c>; a case
/// this port ranks differently names the rule that differs.
/// </remarks>
public sealed class DiscoverFixtureTests
{
    private static readonly Lazy<JsonElement> Root = new(() =>
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Fixtures", "discover-fixture.json");
        using var document = JsonDocument.Parse(File.ReadAllText(path));
        return document.RootElement.Clone();
    });

    public static IEnumerable<object[]> Cases() => Enumerable.Range(0, Root.Value.GetProperty("cases").GetArrayLength()).Select(i => new object[] { i });

    public static IEnumerable<object[]> Weeks() => Enumerable.Range(0, Root.Value.GetProperty("weeks").GetArrayLength()).Select(i => new object[] { i });

    [Theory]
    [MemberData(nameof(Cases))]
    public void Ranks_the_fixture_identically(int index)
    {
        var root = Root.Value;
        var test = root.GetProperty("cases")[index];
        var name = test.GetProperty("name").GetString();

        var library = root.GetProperty("library").EnumerateArray().Select(t =>
        {
            var artist = t.GetProperty("artist").GetString()!;
            return new DiscoverTrack(
                new LibraryTrack(t.GetProperty("id").GetString()!, artist, t.GetProperty("genres").EnumerateArray().Select(g => g.GetString()!).ToList()),
                t.TryGetProperty("trackArtist", out var own) ? own.GetString()! : artist,
                t.TryGetProperty("album", out var album) ? album.GetString() : null);
        }).ToList();

        var plays = (test.TryGetProperty("plays", out var own) ? own : root.GetProperty("plays")).EnumerateArray().Select(p => new PlayEvent(
            p.GetProperty("id").GetString()!,
            p.GetProperty("startedAt").GetInt64(),
            null,
            p.GetProperty("completed").GetBoolean(),
            p.GetProperty("skipped").GetBoolean())).ToList();

        var flags = (test.TryGetProperty("notInterested", out var ownFlags) ? ownFlags : root.GetProperty("notInterested"))
            .EnumerateArray().Select(x => x.GetString()!).ToHashSet(StringComparer.OrdinalIgnoreCase);

        var result = DiscoverRanker.Rank(
            root.GetProperty("userId").GetString()!, library, plays, flags, test.GetProperty("limit").GetInt32(), test.GetProperty("now").GetInt64());

        var expected = test.GetProperty("expected");
        Assert.True(result.Week == expected.GetProperty("week").GetString(), $"{name}: week {result.Week}");
        Assert.True(result.ProfileEvents == expected.GetProperty("profile").GetProperty("events").GetInt32(), $"{name}: events {result.ProfileEvents}");
        Assert.True(result.ProfileSince == expected.GetProperty("profile").GetProperty("since").GetInt64(), $"{name}: since {result.ProfileSince}");

        var want = expected.GetProperty("candidates").EnumerateArray().ToList();
        Assert.True(
            result.Candidates.Select(c => c.Id).SequenceEqual(want.Select(w => w.GetProperty("id").GetString())),
            $"{name}: [{string.Join(", ", result.Candidates.Select(c => c.Id))}], expected [{string.Join(", ", want.Select(w => w.GetProperty("id").GetString()))}]");

        for (var i = 0; i < want.Count; i++)
        {
            var got = result.Candidates[i];
            Assert.True(Rounded(got.Score) == Rounded(want[i].GetProperty("score").GetDouble()), $"{name}: {got.Id} scored {got.Score}");
            Assert.True(Rounded(got.Taste) == Rounded(want[i].GetProperty("factors").GetProperty("taste").GetDouble()), $"{name}: {got.Id} taste {got.Taste}");
        }
    }

    [Theory]
    [MemberData(nameof(Weeks))]
    public void Names_the_iso_week_in_utc(int index)
    {
        var row = Root.Value.GetProperty("weeks")[index];

        var (name, start) = DiscoverRanker.Week(row.GetProperty("now").GetInt64());

        Assert.Equal(row.GetProperty("week").GetString(), name);
        Assert.Equal(row.GetProperty("startMs").GetInt64(), start);
    }

    private static double Rounded(double value) => Math.Round(value * 1_000_000) / 1_000_000;
}
